// Reply Chain Check: skip drafts, sent items, self-sends, and replies to our own emails
try {
  const items = $('Gmail Trigger').all();
  const results = [];

  let ownerEmail = 'info@solideaus.com';
  try {
    ownerEmail = $('Config').first().json.ownerEmail.toLowerCase();
  } catch (e) {}

  for (const item of items) {
    const labels = item.json.labels || item.json.labelIds || [];
    const labelNames = labels.map(l =>
      (typeof l === 'string' ? l : (l.name || l.id || '')).toUpperCase()
    );

    // Skip drafts
    if (labelNames.includes('DRAFT')) continue;

    // Skip sent-only emails (workflow-generated emails like error forwards)
    if (labelNames.length > 0 && !labelNames.includes('INBOX')) continue;

    const fromEmail = (item.json.from || item.json.From || '').toLowerCase();

    // Self-send: only exact ownerEmail match
    if (fromEmail.includes(ownerEmail)) continue;

    // Strip quoted reply text to check only NEW content for our signatures
    const textPlain = (item.json.textPlain || '');
    const tpLines = textPlain.split('\n');
    let cutIdx = tpLines.length;
    for (let li = 0; li < tpLines.length; li++) {
      const ln = tpLines[li].trim();
      if (/^On\s+.{10,80}\s+wrote:\s*$/i.test(ln) || /^-{3,}\s*Original Message/i.test(ln) || /^_{3,}$/.test(ln)) { cutIdx = li; break; }
      if ((ln === '>' || ln.startsWith('> ')) && li > 0) { cutIdx = li; break; }
    }
    const checkText = tpLines.slice(0, cutIdx).join(' ').toLowerCase();

    // Only match phrases exclusive to emails WE sent
    const ourSignatures = [
      'solidea sizing email assistant',
      'd recommend a size',
      'measurements we still need',
      '888-841-8834 | solideaus.com'
    ];
    const isReplyToOurs = ourSignatures.some(sig => checkText.includes(sig));
    if (isReplyToOurs) continue;

    results.push(item);
  }

  return results.length > 0 ? results : [];
} catch (error) {
  return $input.all();
}

// Smart Filter: determine if this email is a sizing inquiry
try {
  const items = $input.all();
  const results = [];

  for (const item of items) {
    const subject = (item.json.subject || '').toLowerCase();
    const rawBody = (item.json.textPlain || item.json.snippet || '');
    const combined = subject + ' ' + rawBody.toLowerCase();
    const bLines = rawBody.split('\n');
    let bCut = bLines.length;
    for (let li = 0; li < bLines.length; li++) {
      const ln = bLines[li].trim();
      if (/^On\s+.{10,80}\s+wrote:\s*$/i.test(ln) || /^-{3,}\s*Original Message/i.test(ln) || /^_{3,}$/.test(ln)) { bCut = li; break; }
      if ((ln === '>' || ln.startsWith('> ')) && li > 0) { bCut = li; break; }
    }
    const newCombined = subject + ' ' + bLines.slice(0, bCut).join(' ').toLowerCase();

    // Exclusion patterns - skip these emails entirely
    const exclusions = [
      'order #', 'order number', 'order confirmation',
      'shipped', 'tracking', 'delivery',
      'unsubscribe', 'opt out', 'opt-out',
      'oversized', 'resize image', 'image size',
      'invoice', 'receipt', 'payment confirmation',
      'return label', 'refund processed',
      '888-841-8834 | solideaus.com',
      'solidea sizing assistant', 'your recommended size',
      'measurements we still need'
    ];

    const isExcluded = exclusions.some(ex => newCombined.includes(ex));
    if (isExcluded) continue;

    // Sizing intent keywords
    const sizingKeywords = [
      'what size', 'which size', 'sizing', 'size recommendation',
      'size guide', 'help with size', 'size chart',
      'recommend a size', 'recommend size', 'right size',
      'correct size', 'best size', 'size advice',
      'need help with fit', 'help me find my size',
      'not sure what size', 'unsure about size'
    ];

    // Measurement keywords
    const measurementKeywords = [
      'cm', 'centimeter', 'inches', 'inch',
      'height', 'weight', 'bust', 'waist', 'hip',
      'calf', 'ankle', 'wrist', 'bicep', 'underbust',
      'arm length', 'circumference',
      'feet', 'foot', 'lbs', 'pounds', 'kg', 'kilogram',
      'measure', 'measurement'
    ];

    const fitKeywords = ['fit', 'fitting', 'compression level', 'too tight', 'too loose'];

    const hasSizingIntent = sizingKeywords.some(kw => combined.includes(kw));
    const hasMeasurement = measurementKeywords.some(kw => combined.includes(kw));
    const hasFitInSubject = fitKeywords.some(kw => subject.includes(kw));

    if (hasSizingIntent || hasMeasurement || hasFitInSubject) {
      results.push(item);
    }
  }

  return results.length > 0 ? results : [];
} catch (error) {
  return $input.all();
}

// Parse Email: detect product type, extract measurements, convert units
// Processes ALL input emails
try {
  function decodeHtml(str) {
    return str.replace(/&#39;/g,"'").replace(/&#x27;/g,"'").replace(/&apos;/g,"'")
      .replace(/&#34;/g,'"').replace(/&quot;/g,'"').replace(/&amp;/g,'&')
      .replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#x2F;/g,'/')
      .replace(/&#(\d+);/g,(m,c)=>String.fromCharCode(parseInt(c,10)));
  }

  const productMap = [
    {type:'arm_sleeves',label:'Arm Sleeves',patterns:[/\barm\s*sleeves?\b/,/\barm-sleeves?\b/,/\barmsleeves?\b/,/\barmband\b/,/\bgauntlet\b/,/\bcompression\s+arm\b/]},
    {type:'capris',label:'Capris',patterns:[/\bcapris?\b/,/\bopaque\s+capri\b/]},
    {type:'leggings',label:'Leggings',patterns:[/\bleggings?\b/,/\btights\b/,/\bpantyhose\b/,/\bbike\s+shorts?\b/,/\bcompression\s+shorts?\b/,/\bmen'?s?\s+briefs?\b/,/\blong\s+briefs?\b/,/\bshort\s+briefs?\b/,/\bactive\s+massage\s+legging\b/,/\bopaque\s+legging\b/,/\bhigh\s+waist\s+legging\b/,/\bmaternity\s+legging\b/]},
    {type:'socks',label:'Compression Socks',patterns:[/\bsocks?\b/,/\bknee[\s-]?highs?\b/,/\bkneehighs?\b/,/\bankle\s+socks?\b/,/\bmid[\s-]?calf\b/,/\bcalf\s+sleeves?\b/,/\bthigh\s+highs?\b/,/\bcompression\s+socks?\b/,/\bclosed\s+toe\s+knee\b/]},
    {type:'bras',label:'Bras',patterns:[/\bbras?\b/,/\bbraless\s+top\b/,/\btank\s+top\b/,/\bcompression\s+top\b/,/\bbodysuit\b/,/\bbuilt[\s-]?in\s+bra\b/,/\bsports\s+bra\b/,/\bcompression\s+bra\b/]}
  ];

  const requiredMeasurements = {
    arm_sleeves:['bicep_circumference_cm','wrist_circumference_cm','arm_length_cm'],
    leggings:['height_cm','weight_kg','hip_circumference_cm','waist_circumference_cm'],
    capris:['height_cm','weight_kg','hip_circumference_cm','waist_circumference_cm'],
    socks:['calf_circumference_cm','ankle_circumference_cm'],
    bras:['bust_circumference_cm','underbust_circumference_cm']
  };

  function feetInchesToCm(f,i){return((f*12)+(i||0))*2.54;}
  function inToCm(v){return v*2.54;}
  function lbsToKg(v){return v/2.2046;}
  const numberWords={zero:0,one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12};
  function parseNum(s){const k=s.trim().toLowerCase();if(numberWords[k]!==undefined)return numberWords[k];const n=parseFloat(k);return isNaN(n)?null:n;}

  function extractValue(text,patterns){
    for(const p of patterns){const m=text.match(p.regex);if(m){let v;
      if(p.type==='feet_inches'){const f=parseNum(m[1]);const i=m[2]?parseNum(m[2]):0;if(f===null)continue;v=feetInchesToCm(f,i||0);}
      else{v=parseNum(m[1]);if(v===null)continue;if(p.unit==='inches')v=inToCm(v);if(p.unit==='lbs')v=lbsToKg(v);}
      return Math.round(v*100)/100;}}return null;}

  const heightPatterns=[
    {regex:/(\d+)\s*'\s*(\d+)?\s*"?/,type:'feet_inches'},
    {regex:/(\d+)\s*(?:feet|foot|ft)\.?\s*(\d+)?\s*(?:inches|inch|in)?/i,type:'feet_inches'},
    {regex:/(\w+)\s+foot\s+(\w+)/i,type:'feet_inches'},
    {regex:/(\w+)\s+feet\s+(\w+)/i,type:'feet_inches'},
    {regex:/height\s*(?:is|:|=)?\s*([\d.]+)\s*cm/i,unit:'cm'},
    {regex:/([\d.]+)\s*cm\s*(?:tall|height)/i,unit:'cm'},
    {regex:/i(?:'m|\s+am)\s+([\d.]+)\s*cm/i,unit:'cm'},
    {regex:/height\s*(?:is|:|=)?\s*([\d.]+)\s*(?:in|inches)/i,unit:'inches'},
    {regex:/height\s*(?:is|:|=)?\s*([\d.]+)/i,unit:'cm'}
  ];
  const weightPatterns=[
    {regex:/(?:weight|weigh)\s+(?:about|around|approximately)?\s*([\d.]+)\s*(?:lbs?|pounds?)/i,unit:'lbs'},
    {regex:/(?:weight|weigh)[:\s]+([\d.]+)\s*(?:lbs?|pounds?)/i,unit:'lbs'},
    {regex:/([\d.]+)\s*(?:lbs?|pounds?)(?:\s|$|,|\.|and)/i,unit:'lbs'},
    {regex:/(?:weight|weigh)\s+(?:about|around|approximately)?\s*([\d.]+)\s*(?:kg|kilogram)/i,unit:'cm'},
    {regex:/(?:weight|weigh)[:\s]+([\d.]+)\s*(?:kg|kilogram)/i,unit:'cm'},
    {regex:/([\d.]+)\s*(?:kg|kilogram)s?(?:\s|$|,|\.|and)/i,unit:'cm'},
    {regex:/(?:weight|weigh)\s+(?:about|around|approximately)?\s*([\d.]+)/i,unit:'lbs'}
  ];

  function circumPat(name){
    const n=name.replace(/_/g,'[\\s-]?');
    return [
      {regex:new RegExp(n+'\\s+(?:is|are|of|about|around|approximately|measures?|measuring)?\\s*([\\d.]+)\\s*(?:in|inches|\\")', 'i'),unit:'inches'},
      {regex:new RegExp('([\\d.]+)\\s*(?:in|inches|inch)\\s*'+n,'i'),unit:'inches'},
      {regex:new RegExp(n+'[:\\s]+([\\d.]+)\\s*(?:in|inches|\\")', 'i'),unit:'inches'},
      {regex:new RegExp(n+'\\s+(?:is|are|of|about|around|approximately|measures?|measuring)?\\s*([\\d.]+)\\s*cm','i'),unit:'cm'},
      {regex:new RegExp('([\\d.]+)\\s*cm\\s*'+n,'i'),unit:'cm'},
      {regex:new RegExp(n+'[:\\s]+([\\d.]+)\\s*cm','i'),unit:'cm'},
      {regex:new RegExp('my\\s+'+n+'\\s+(?:is|are|measures?)\\s+(?:about|around|approximately)?\\s*([\\d.]+)\\s*(?:in|inches|\\")', 'i'),unit:'inches'},
      {regex:new RegExp('my\\s+'+n+'\\s+(?:is|are|measures?)\\s+(?:about|around|approximately)?\\s*([\\d.]+)\\s*cm','i'),unit:'cm'},
      {regex:new RegExp('my\\s+'+n+'\\s+(?:is|are|measures?)\\s+(?:about|around|approximately)?\\s*([\\d.]+)','i'),unit:'cm'},
      {regex:new RegExp(n+'\\s+(?:is|are|of|about|around|approximately|measures?|measuring)?\\s*([\\d.]+)','i'),unit:'cm'},
      {regex:new RegExp(n+'[:\\s]+([\\d.]+)','i'),unit:'cm'}
    ];
  }

  const bodyParts=[
    {key:'bust_circumference_cm',names:['bust']},
    {key:'underbust_circumference_cm',names:['underbust','under bust','under-bust']},
    {key:'waist_circumference_cm',names:['waist']},
    {key:'hip_circumference_cm',names:['hip','hips']},
    {key:'calf_circumference_cm',names:['calf']},
    {key:'ankle_circumference_cm',names:['ankle']},
    {key:'bicep_circumference_cm',names:['bicep','upper arm','upper-arm']},
    {key:'wrist_circumference_cm',names:['wrist']},
    {key:'arm_length_cm',names:['arm length','arm-length']}
  ];

  function parseOne(item) {
    let body = (item.json.textPlain || item.json.snippet || '');
    const subject = (item.json.subject || '');
    body = decodeHtml(body);
    const bodyLower = body.toLowerCase();
    const combined = subject.toLowerCase() + ' ' + bodyLower;

    const detectedProducts = [];
    for (const prod of productMap) {
      for (const pat of prod.patterns) {
        if (pat.test(combined)) { detectedProducts.push({type:prod.type,label:prod.label}); break; }
      }
    }

    const measurements = {};
    const hv = extractValue(bodyLower, heightPatterns); if (hv) measurements.height_cm = hv;
    const wv = extractValue(bodyLower, weightPatterns); if (wv) measurements.weight_kg = wv;
    for (const part of bodyParts) {
      for (const name of part.names) {
        const v = extractValue(bodyLower, circumPat(name));
        if (v) { measurements[part.key] = v; break; }
      }
    }

    const products = []; let hasProcessable = false; let hasMissing = false;
    for (const prod of detectedProducts) {
      const req = requiredMeasurements[prod.type] || [];
      const pm = {}; const miss = [];
      for (const r of req) { if (measurements[r] !== undefined) pm[r] = measurements[r]; else miss.push(r); }
      const can = miss.length === 0;
      if (can) hasProcessable = true;
      if (miss.length > 0) hasMissing = true;
      products.push({productType:prod.type,productLabel:prod.label,measurements:pm,missingMeasurements:miss,canProcess:can});
    }

    // Extract sender email robustly
    const rawFrom = item.json.from || item.json.From || item.json.sender || item.json.senderAddress || '';
    let senderEmail = rawFrom;
    let senderName = '';
    const angleMatch = rawFrom.match(/<([^>]+@[^>]+)>/);
    if (angleMatch) { senderEmail = angleMatch[1].trim(); senderName = rawFrom.split('<')[0].replace(/[^a-zA-Z0-9 .'-]/g, '').trim(); }
    if (!senderName) senderName = item.json.fromName || item.json.senderName || '';
    if (!senderName && senderEmail.includes('@')) senderName = senderEmail.split('@')[0];
    if (!senderName) senderName = 'Customer';

    return {
      fromEmail: senderEmail,
      fromName: senderName,
      subject, messageId: item.json.messageId || item.json.id || '',
      threadId: item.json.threadId || '', originalBody: body,
      products, allMeasurements: measurements,
      hasProcessableProduct: hasProcessable,
      hasMissingMeasurements: hasMissing && !hasProcessable,
      hasNoProduct: detectedProducts.length === 0
    };
  }

  return $input.all().map(item => {
    try { return { json: parseOne(item) }; }
    catch (e) { return { json: {
      fromEmail:item.json.from||'',fromName:'',subject:item.json.subject||'',
      messageId:'',threadId:'',originalBody:item.json.textPlain||'',
      products:[],allMeasurements:{},hasProcessableProduct:false,
      hasMissingMeasurements:false,hasNoProduct:true,parseError:e.message
    }};}
  });
} catch (error) {
  return $input.all().map(item => ({ json: {
    fromEmail:item.json.from||'',fromName:'',subject:item.json.subject||'',
    messageId:'',threadId:'',originalBody:'',products:[],allMeasurements:{},
    hasProcessableProduct:false,hasMissingMeasurements:false,hasNoProduct:true,
    parseError:error.message
  }}));
}

// Prepare API request — one item per processable product, carries ALL data forward
try {
  let apiBaseUrl = 'https://web-production-762f7.up.railway.app';
  try { apiBaseUrl = $('Config').first().json.apiBaseUrl; } catch(e) {}

  const output = [];
  for (const item of $input.all()) {
    const data = item.json;
    const processable = (data.products || []).filter(p => p.canProcess);
    for (const prod of processable) {
      output.push({ json: {
        ...data,
        currentProduct: prod,
        apiUrl: apiBaseUrl + '/api/v1/size-recommendation',
        apiBody: { product_type: prod.productType, measurements: prod.measurements }
      }});
    }
  }
  return output;
} catch (error) {
  return $input.all().map(item => ({ json: { error: error.message, ...item.json } }));
}

// Merge API response with original request data from Prepare API Request
// (HTTP Request node replaces input data with response, so we recover originals here)
const responses = $input.all();
const originals = $('Prepare API Request').all();
const output = [];

for (let i = 0; i < originals.length; i++) {
  const orig = originals[i].json;
  const resp = responses[i] ? responses[i].json : {};

  if (resp.recommended_size) {
    output.push({ json: {
      ...orig,
      recommended_size: resp.recommended_size,
      confidence: resp.confidence,
      notes: resp.notes || '',
      apiSuccess: true
    }});
  } else {
    output.push({ json: {
      ...orig,
      apiSuccess: false,
      apiError: resp.error || resp.message || 'API request failed'
    }});
  }
}

return output;

// Merge retry response with original data
// Get the failed items from Merge API Response (they have all original data)
const responses = $input.all();
const allMerged = $('Merge API Response').all();
const failedItems = allMerged.filter(item => !item.json.apiSuccess);
const output = [];

for (let i = 0; i < responses.length; i++) {
  const orig = failedItems[i] ? failedItems[i].json : {};
  const resp = responses[i] ? responses[i].json : {};

  if (resp.recommended_size) {
    output.push({ json: {
      ...orig,
      recommended_size: resp.recommended_size,
      confidence: resp.confidence,
      notes: resp.notes || '',
      apiSuccess: true
    }});
  } else {
    output.push({ json: {
      ...orig,
      apiSuccess: false,
      apiError: resp.error || resp.message || 'Retry failed'
    }});
  }
}

return output;

// Format sizing recommendation reply — groups multiple products per email
try {
  const items = $input.all();

  // Group by messageId (same email may have multiple product recommendations)
  const groups = {};
  for (const item of items) {
    const key = item.json.messageId || item.json.fromEmail || 'unknown';
    if (!groups[key]) groups[key] = [];
    groups[key].push(item.json);
  }

  const results = [];
  for (const key of Object.keys(groups)) {
    const emailItems = groups[key];
    const first = emailItems[0];
    const name = first.fromName || 'there';
    const multi = emailItems.length > 1;

    let recsHtml = '';
    let recsText = '';
    const allProducts = [];

    for (const d of emailItems) {
      const label = d.currentProduct.productLabel;
      const size = d.recommended_size;
      const conf = d.confidence || 'exact';
      const notes = d.notes || '';

      let rec = '';
      if (multi) {
        if (conf === 'exact') {
          rec = 'For our ' + label + ', I\u2019d recommend a <b>size ' + size + '</b> \u2014 that should be a great fit!';
        } else if (conf === 'interpolated') {
          rec = 'For our ' + label + ', I\u2019d suggest a <b>size ' + size + '</b>. You\u2019re right between sizes, and ' + size + ' should give you the best balance of compression and comfort.';
        } else {
          rec = 'For our ' + label + ', I think a <b>size ' + size + '</b> would be your closest match.';
        }
      } else {
        if (conf === 'exact') {
          rec = 'Based on the measurements you shared, I\u2019d recommend a <b>size ' + size + '</b> in our ' + label + '. That should be a great fit for you!';
        } else if (conf === 'interpolated') {
          rec = 'Based on your measurements, I\u2019d suggest going with a <b>size ' + size + '</b> in our ' + label + '. You\u2019re right between sizes, and ' + size + ' should give you the best balance of compression and comfort.';
        } else {
          rec = 'Your measurements are a little outside our standard chart for the ' + label + ', but I think a <b>size ' + size + '</b> would be your closest match. If you\u2019d like to talk through the fit in more detail, feel free to give us a call \u2014 I\u2019m happy to help!';
        }
      }

      recsHtml += '<p>' + rec + '</p>';
      if (notes) recsHtml += '<p>' + notes + '</p>';
      recsText += rec.replace(/<[^>]*>/g, '') + '\n' + (notes ? notes + '\n' : '') + '\n';

      allProducts.push({
        productType: d.currentProduct.productType, productLabel: label,
        recommendedSize: size, confidence: conf, notes, measurements: d.currentProduct.measurements
      });
    }

    // Check for products with missing measurements (multi-product case)
    const allProds = first.products || [];
    const incomplete = allProds.filter(p => !p.canProcess && p.missingMeasurements && p.missingMeasurements.length > 0);
    let missingHtml = '';
    let missingText = '';
    if (incomplete.length > 0) {
      const mLbls = {'height_cm':'your height','weight_kg':'your weight','bust_circumference_cm':'bust circumference','underbust_circumference_cm':'underbust circumference','waist_circumference_cm':'waist circumference','hip_circumference_cm':'hip circumference','calf_circumference_cm':'calf circumference','ankle_circumference_cm':'ankle circumference','bicep_circumference_cm':'bicep circumference','wrist_circumference_cm':'wrist circumference','arm_length_cm':'arm length'};
      for (const ip of incomplete) {
        const ml = ip.missingMeasurements.map(m => mLbls[m] || m);
        missingHtml += '<p>I\u2019d also love to help with our ' + ip.productLabel + '! To get you a size, could you send me ' + ml.join(', ') + '?</p>';
        missingText += 'I\u2019d also love to help with our ' + ip.productLabel + '! To get you a size, could you send me ' + ml.join(', ') + '?\n\n';
      }
    }

    const htmlBody = '<p>Hi ' + name + ',</p><p>Thanks so much for reaching out!</p>' +
      (multi ? '<p>I looked up sizes for everything you asked about:</p>' : '') +
      recsHtml + missingHtml +
      '<p>One quick tip \u2014 with compression garments, if you\u2019re ever between sizes, going up a size usually feels more comfortable without losing any of the benefits.</p>' +
      '<p>Let me know if you have any other questions \u2014 happy to help!</p>' +
      '<p>Best,<br>Solidea US<br>888-841-8834 | <a href="https://www.solideaus.com">solideaus.com</a></p>';

    const plainText = 'Hi ' + name + ',\n\nThanks so much for reaching out!\n\n' +
      (multi ? 'I looked up sizes for everything you asked about:\n\n' : '') +
      recsText + missingText +
      'One quick tip \u2014 with compression garments, if you\u2019re ever between sizes, going up a size usually feels more comfortable without losing any of the benefits.\n\n' +
      'Let me know if you have any other questions \u2014 happy to help!\n\nBest,\nSolidea US\n888-841-8834 | solideaus.com';

    results.push({ json: {
      toEmail: first.fromEmail, subject: 'Re: ' + first.subject,
      htmlBody, plainText,
      recommendedSize: allProducts.map(p => p.productLabel + ': ' + p.recommendedSize).join(', '),
      confidence: allProducts[0].confidence,
      notes: allProducts.map(p => p.notes).filter(n => n).join('; '),
      productType: allProducts.map(p => p.productType).join(', '),
      productLabel: allProducts.map(p => p.productLabel).join(', '),
      measurements: first.currentProduct.measurements,
      products: allProducts,
      threadId: first.threadId, messageId: first.messageId,
      fromName: first.fromName, fromEmail: first.fromEmail
    }});
  }

  return results;
} catch (error) {
  const d = ($input.first() || {json:{}}).json;
  return [{ json: { error: error.message, toEmail: d.fromEmail||'', subject: 'Re: ' + (d.subject||'') }}];
}

// Log success — processes all items
try {
  const fmtM=(m)=>{if(!m||Object.keys(m).length===0)return 'None';const N={height_cm:'Height',weight_kg:'Weight',bust_circumference_cm:'Bust',underbust_circumference_cm:'Underbust',waist_circumference_cm:'Waist',hip_circumference_cm:'Hip',calf_circumference_cm:'Calf',ankle_circumference_cm:'Ankle',bicep_circumference_cm:'Bicep',wrist_circumference_cm:'Wrist',arm_length_cm:'Arm length'};return Object.entries(m).map(([k,v])=>(N[k]||k)+': '+v+(k==='weight_kg'?' kg':' cm')).join(', ');};
